package cn.xi.cloudwidget;
import android.app.*;
import android.appwidget.*;
import android.content.*;
import android.graphics.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.xmlpull.v1.*;
import java.io.*;
import java.util.*;

/** Focused regressions for REVIEW-v030-20261028, not old aggregate evidence. */
public class ReviewFixChecks extends RefactorChecks {
    interface Work {void run()throws Exception;}
    void main(Work work)throws Throwable{Throwable[] error={null};runOnMainSync(()->{try{work.run();}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw error[0];}
    void png(Bitmap image,String name)throws Exception{File dir=new File(c.getFilesDir(),"review031");dir.mkdirs();try(OutputStream stream=new FileOutputStream(new File(dir,name))){image.compress(Bitmap.CompressFormat.PNG,100,stream);}}
    static <T> void collect(View view,Class<T> kind,List<T> result){if(kind.isInstance(view))result.add(kind.cast(view));if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int n=0;n<group.getChildCount();n++)collect(group.getChildAt(n),kind,result);}}
    static int dark(Bitmap image,RectF region){int count=0;for(int y=Math.max(0,(int)region.top);y<Math.min(image.getHeight(),region.bottom);y++)for(int x=Math.max(0,(int)region.left);x<Math.min(image.getWidth(),region.right);x++){int p=image.getPixel(x,y);if(Color.alpha(p)>180&&Color.red(p)<80&&Color.green(p)<80&&Color.blue(p)<80)count++;}return count;}
    static RectF region(CardLayout layout,float top,float height){return new RectF(layout.left+layout.pad*layout.scale,layout.top+top*layout.scale,layout.left+(layout.baseWidth-layout.pad)*layout.scale,layout.top+(top+height)*layout.scale);}
    static int hash(View view){Bitmap image=Bitmap.createBitmap(view.getWidth(),view.getHeight(),Bitmap.Config.ARGB_8888);view.draw(new Canvas(image));int[] pixels=new int[image.getWidth()*image.getHeight()];image.getPixels(pixels,0,image.getWidth(),0,0,image.getWidth(),image.getHeight());image.recycle();return Arrays.hashCode(pixels);}
    static void seek(SeekBar bar,float from,float to,int action){long time=SystemClock.uptimeMillis();float y=bar.getHeight()/2f;MotionEvent event=MotionEvent.obtain(time,time,action,bar.getPaddingLeft()+(bar.getWidth()-bar.getPaddingLeft()-bar.getPaddingRight())*(action==MotionEvent.ACTION_DOWN?from:to),y,0);bar.onTouchEvent(event);event.recycle();}
    @Override public void onStart(){String phase=args.getString("phase","");if(phase.equals("smoke")){super.onStart();return;}Bundle output=new Bundle();try{c=getTargetContext();
        if(phase.equals("upgrade")){
            XmlPullParser parser=android.util.Xml.newPullParser();try(InputStream input=getContext().getAssets().open("v030-snapshot.xml")){parser.setInput(input,"UTF-8");int e;while((e=parser.next())!=XmlPullParser.END_DOCUMENT)if(e==XmlPullParser.START_TAG&&"string".equals(parser.getName())){String key=parser.getAttributeValue(null,"name"),value=parser.nextText();check(value.equals(c.getSharedPreferences("cards-v1",0).getString(key,null)),"v030 raw preference unchanged "+key);}}
        }else if(phase.equals("tick")){
            ReviewHostActivity host=(ReviewHostActivity)startActivitySync(new Intent(c,ReviewHostActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();ArrayList<TextClock> clocks=new ArrayList<>();long ready=SystemClock.uptimeMillis()+5000;while(clocks.size()<4&&SystemClock.uptimeMillis()<ready){clocks.clear();main(()->collect(host.getWindow().getDecorView(),TextClock.class,clocks));SystemClock.sleep(100);}check(clocks.size()==4,"two real widget instances contain native time and date TextClocks");ArrayList<TextClock> times=new ArrayList<>();for(TextClock clock:clocks)if(clock.getId()==R.id.clock)times.add(clock);String[] before=new String[2];main(()->{for(int n=0;n<2;n++)before[n]=times.get(n).getText().toString();});long deadline=SystemClock.uptimeMillis()+65000;boolean[] changed={false,false};while(SystemClock.uptimeMillis()<deadline&&(!changed[0]||!changed[1])){SystemClock.sleep(500);main(()->{for(int n=0;n<2;n++)changed[n]=!before[n].equals(times.get(n).getText().toString());});}for(int n=0;n<2;n++)check(changed[n],"native TextClock advances without a widget bitmap refresh shape "+n);
        }else {
            alpha();layers();thumbs();
        }
        output.putString("stream",report+"Checks passed this run: "+count+"\n");finish(Activity.RESULT_OK,output);
    }catch(Throwable e){output.putString("stream",report+"FAIL "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,output);}}
    void alpha()throws Exception{
        Bitmap image=Bitmap.createBitmap(64,64,Bitmap.Config.ARGB_8888);image.eraseColor(0xff5082ae);File dir=new File(c.getFilesDir(),"photos");dir.mkdirs();String filename="review031-opaque.png";try(OutputStream stream=new FileOutputStream(new File(dir,filename))){image.compress(Bitmap.CompressFormat.PNG,100,stream);}image.eraseColor(Color.TRANSPARENT);Paint paint=new Paint();paint.setColor(0xff5082ae);new Canvas(image).drawRect(0,0,32,64,paint);ByteArrayOutputStream bytes=new ByteArrayOutputStream();image.compress(Bitmap.CompressFormat.PNG,100,bytes);image.recycle();String ref=new AssetStore(c).importPng(new ByteArrayInputStream(bytes.toByteArray())).ref;
        for(int mode:new int[]{0,2,3})for(int opacity:new int[]{0,25,50,100}){
            Card card=new Card();card.type=3;card.background=0xfff7e8d5;card.bgMode=mode;card.backgroundPhoto=filename;card.backgroundAsset=ref;card.opacity=opacity;Bitmap rendered=Renderer.render(c,card,200,200,false);int expected=opacity*255/100;
            for(int x:new int[]{50,150})check(Math.abs(Color.alpha(rendered.getPixel(x,100))-expected)<=1,"single opacity alpha mode/percent/x "+mode+"/"+opacity+"/"+x);
            if(opacity>0){int left=rendered.getPixel(50,100),right=rendered.getPixel(150,100);int expectedLeft=mode==0?card.background:0xff5082ae,expectedRight=mode==3?card.background:expectedLeft;check(rgbClose(left,expectedLeft)&&rgbClose(right,expectedRight),"image colors are composed before opacity mode/percent "+mode+"/"+opacity);}
            png(rendered,"alpha-"+mode+"-"+opacity+".png");rendered.recycle();card.grid=true;Bitmap grid=Renderer.render(c,card,200,200,false);check(Math.abs(Color.alpha(grid.getPixel(30,30))-expected)<=1,"grid shares background group alpha "+mode+"/"+opacity);grid.recycle();
        }
        Card foreground=new Card();foreground.type=3;foreground.font=0;foreground.body="FOREGROUND";foreground.ink=0xff111111;foreground.opacity=0;foreground.border=4;foreground.addSticker(ReviewFixtures.opaque(c));foreground.stickers.getJSONObject(0).put("x",.5).put("y",.8);Bitmap rendered=Renderer.render(c,foreground,200,200,false);check(Color.alpha(rendered.getPixel(100,160))==255,"zero background opacity leaves sticker fully opaque");check(dark(rendered,new RectF(16,28,184,80))>20,"zero background opacity leaves body fully visible");int max=0;for(int x=3;x<10;x++)max=Math.max(max,Color.alpha(rendered.getPixel(x,100)));check(max==255,"zero background opacity leaves border fully opaque");png(rendered,"foreground-opacity-zero.png");rendered.recycle();
    }
    boolean rgbClose(int actual,int expected){return Math.abs(Color.red(actual)-Color.red(expected))<=3&&Math.abs(Color.green(actual)-Color.green(expected))<=3&&Math.abs(Color.blue(actual)-Color.blue(expected))<=3;}
    void layers()throws Throwable{
        ReviewHostActivity host=(ReviewHostActivity)startActivitySync(new Intent(c,ReviewHostActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();ArrayList<AppWidgetHostView> nativeViews=new ArrayList<>();long ready=SystemClock.uptimeMillis()+8000;boolean[] initialized={false};
        while(!initialized[0]&&SystemClock.uptimeMillis()<ready){main(()->{nativeViews.clear();collect(host.getWindow().getDecorView(),AppWidgetHostView.class,nativeViews);initialized[0]=nativeViews.size()==2;for(AppWidgetHostView view:nativeViews){TextClock clock=view.findViewById(R.id.clock);initialized[0]&=view.getWidth()>0&&clock!=null&&clock.getText().length()>0;}});if(!initialized[0])SystemClock.sleep(100);}check(initialized[0],"two real attached AppWidgetHostViews initialized");
        for(int shape=0;shape<2;shape++){
            Card card=ReviewFixtures.overlap(c,shape);AppWidgetHostView view=nativeViews.get(shape);int width=view.getWidth(),height=view.getHeight();Bitmap preview=Renderer.render(c,card,width,height,true),base=Renderer.render(c,card,width,height,false);CardLayout layout=new CardLayout(card,width,height);RectF clock=region(layout,layout.clockTop(),layout.clockLine()),date=region(layout,layout.clockTop()+layout.clockLine(),layout.dateLine()),body=region(layout,layout.bodyTop(),30);
            check(dark(base,clock)==0&&dark(base,date)==0,"opaque stickers cover the bitmap time/date region "+shape);check(dark(preview,clock)>20&&dark(preview,date)>20,"preview time and date stay above overlapping stickers "+shape);check(dark(preview,body)==0&&dark(base,body)==0,"body remains below stickers in both bitmap paths "+shape);
            final Bitmap[] actual={null};main(()->{actual[0]=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);view.draw(new Canvas(actual[0]));});png(preview,"overlap-preview-"+shape+".png");png(actual[0],"overlap-remoteviews-"+shape+".png");
            check(dark(actual[0],clock)>20&&dark(actual[0],date)>20,"actual attached RemoteViews time/date stay above stickers "+shape);check(dark(actual[0],body)==0,"actual RemoteViews body stays below stickers "+shape);preview.recycle();base.recycle();actual[0].recycle();
        }
    }
    void thumbs()throws Throwable{
        Card source=new Card();source.id="qa034-live-border";source.type=3;source.body="边框实时预览";source.border=3;new Store(c).save(source);EditorActivity editor=(EditorActivity)startActivitySync(new Intent(c,GalleryEditorActivity.class).putExtra("card",source.id).putExtra("tab",3).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitForIdleSync();Card draft=(Card)field("card").get(editor);LinearLayout panel=(LinearLayout)field("panel").get(editor);ArrayList<Controls.BorderThumb> thumbs=new ArrayList<>();ArrayList<SeekBar> sliders=new ArrayList<>();main(()->{collect(panel,Controls.BorderThumb.class,thumbs);collect(panel,SeekBar.class,sliders);});check(thumbs.size()==10&&sliders.size()==2,"ten live border thumbnails and two sliders present");Controls.BorderThumb selected=thumbs.get(3);SeekBar thickness=sliders.get(0),corner=sliders.get(1);int[] prior={0};main(()->prior[0]=hash(selected));float oldWidth=draft.borderWidth;
        main(()->{seek(thickness,.2f,.2f,MotionEvent.ACTION_DOWN);seek(thickness,.2f,.6f,MotionEvent.ACTION_MOVE);});check(draft.borderWidth!=oldWidth,"native thickness drag updates draft while pointer remains down");main(()->check(hash(selected)!=prior[0],"border thumbnail redraws mid-drag thickness"));main(()->{prior[0]=hash(selected);seek(thickness,.6f,.9f,MotionEvent.ACTION_MOVE);});main(()->check(hash(selected)!=prior[0],"same thumbnail updates during continued thickness drag"));main(()->seek(thickness,.9f,.9f,MotionEvent.ACTION_UP));
        main(()->{prior[0]=hash(selected);seek(corner,.66f,.66f,MotionEvent.ACTION_DOWN);seek(corner,.66f,.03f,MotionEvent.ACTION_MOVE);});main(()->check(hash(selected)!=prior[0],"same thumbnail updates mid-drag corner radius"));main(()->seek(corner,.03f,.03f,MotionEvent.ACTION_UP));ArrayList<SeekBar> current=new ArrayList<>();ArrayList<Controls.BorderThumb> currentThumbs=new ArrayList<>();main(()->{collect(panel,SeekBar.class,current);collect(panel,Controls.BorderThumb.class,currentThumbs);});check(current.get(0)==thickness&&current.get(1)==corner&&currentThumbs.get(3)==selected,"dragging retains slider and thumbnail instances");check(draft.border==3&&selected.style==3&&selected.source==draft,"style selection retained and thumbnails read live draft");main(()->{Bitmap capture=Bitmap.createBitmap(selected.getWidth(),selected.getHeight(),Bitmap.Config.ARGB_8888);selected.draw(new Canvas(capture));png(capture,"border-thumbnail-after-drag.png");capture.recycle();editor.save();});Card saved=new Store(c).get(source.id);check(saved.borderWidth==draft.borderWidth&&saved.corner==draft.corner,"dragged border parameters persist through save");
    }
}
